/**
 * Read-only access to the content exported from the legacy MySQL dump
 * (src/data/db/*.json, generated by scripts/import-sql.py).
 * Filters and ordering mirror the legacy CodeIgniter models.
 */
import activities from '../data/db/activities.json';
import advertiser from '../data/db/advertiser.json';
import assessment from '../data/db/assessment.json';
import assessmentAnswer from '../data/db/assessment_answer.json';
import assessmentCase from '../data/db/assessment_case.json';
import assessmentQuestion from '../data/db/assessment_question.json';
import blog from '../data/db/blog.json';
import categories from '../data/db/categories.json';
import contents from '../data/db/contents.json';
import menu from '../data/db/menu.json';
import positionads from '../data/db/positionads.json';
import promotions from '../data/db/promotions.json';
import reviews from '../data/db/reviews.json';
import services from '../data/db/services.json';
import sites from '../data/db/sites.json';
import subcategories from '../data/db/subcategories.json';
import teamgroup from '../data/db/teamgroup.json';
import teams from '../data/db/teams.json';
import times from '../data/db/times.json';
import video from '../data/db/video.json';

import { pick, type Lang } from './i18n';
import { slug } from './text';

export type Row = Record<string, any>;

const active = (rows: Row[]) => rows.filter((r) => r.status === 'A');
const byIdDesc = (rows: Row[]) => [...rows].sort((a, b) => b.id - a.id);
const byIdAsc = (rows: Row[]) => [...rows].sort((a, b) => a.id - b.id);

/** Site-wide settings (legacy webconfig()). */
export const site: Row = sites[0];

// Article-like tables: status 'A', newest first.
export const getPromotions = () => byIdDesc(active(promotions));
export const getBlogs = () => byIdDesc(active(blog));
export const getActivities = () => byIdDesc(active(activities));
export const getReviews = () => byIdDesc(active(reviews));
export const getVideos = () => byIdDesc(active(video));
export const getServices = () => byIdDesc(active(services));

export const getCategories = () => byIdAsc(active(categories));
export const getCategory = (id: number) => categories.find((c: Row) => c.id === id);
export const getSubcategories = (categoryId: number) =>
  byIdAsc(active(subcategories).filter((s) => s.category_id === categoryId));
export const getServicesByCategory = (categoryId: number) =>
  getServices().filter((s) => Number(s.category_id) === categoryId);

export const getTeamGroups = () => byIdAsc(active(teamgroup));
export const getTeams = () => byIdAsc(active(teams));
export const getTimes = () => byIdAsc(times as Row[]);

/** Static pages (`contents` has no language columns). */
export const getContent = (id: number) => active(contents).find((c) => c.id === id);
export const getContents = () => active(contents);

// Self-assessment: status 'N' assessments are listed but shown disabled.
export const getAssessments = () => byIdAsc(assessment.filter((a: Row) => a.status === 'A' || a.status === 'N'));
export const getAssessmentQuestions = (assessmentId: number) =>
  byIdAsc(active(assessmentQuestion).filter((q) => Number(q.category_id) === assessmentId));
export const getAssessmentAnswers = (questionId: number) =>
  active(assessmentAnswer)
    .filter((a) => Number(a.question_id) === questionId)
    .sort((a, b) => Number(a.score) - Number(b.score));
export const getAssessmentCases = (assessmentId: number) =>
  assessmentCase.filter((c: Row) => Number(c.assessment_id) === assessmentId && c.status === 'A');

/** Current banner for an ad position slug (legacy advertiser model). */
export function getBanner(positionSlug: string) {
  const pos = positionads.find((p: Row) => String(p.slug) === positionSlug);
  if (!pos) return undefined;
  const today = new Date().toISOString().slice(0, 10);
  const ad = byIdDesc(active(advertiser)).find(
    (a) =>
      Number(a.positionads_id) === pos.id &&
      /\.(jpe?g|png|gif|webp)$/i.test(a.photomain ?? '') &&
      (!a.startdate || a.startdate.slice(0, 10) <= today || a.startdate.startsWith('0000')) &&
      (!a.enddate || a.enddate.slice(0, 10) >= today || a.enddate.startsWith('0000')),
  ) ?? byIdDesc(active(advertiser)).find((a) => Number(a.positionads_id) === pos.id && /\.(jpe?g|png|gif|webp)$/i.test(a.photomain ?? ''));
  if (!ad) return undefined;
  return { ...ad, src: `/assets/uploads/img_advertiser/${pos.id}/${pos.width}x${pos.height}/${ad.photomain}` };
}

/** Image URLs, matching the legacy upload folder layout. */
export const img = {
  services: (f: string) => `/assets/uploads/img_services/main/${f}`,
  promotions: (f: string) => `/assets/uploads/img_promotions/main/${f}`,
  blog: (f: string) => `/assets/uploads/img_blog/main/${f}`,
  activities: (f: string) => `/assets/uploads/img_activities/main/${f}`,
  reviews: (f: string) => `/assets/uploads/img_reviews/main/${f}`,
  video: (f: string) => `/assets/uploads/img_video/main/${f}`,
  team: (t: Row) => `/assets/uploads/img_teams/${t.category_id}/main/${t.photomain}`,
  teamSquare: (t: Row) => `/assets/uploads/img_teams/${t.category_id}/500x500/${t.photomain2}`,
  category: (f: string) => `/assets/uploads/img_category/${f}`,
  assessment: (f: string) => `/assets/uploads/img_assessment/${f}`,
  assessmentCase: (f: string) => `/assets/uploads/img_assessmentcase/${f}`,
};
export const theme = (f: string) => `/assets/layouts/frontend/images/${f}`;

/** Header menu tree (legacy template/frontend::header). */
export interface MenuItem {
  id: number;
  row: Row;
  href: string | null; // null = "#!" toggle-only item
  children: MenuItem[];
}

export function getMenu(lang: Lang, urlFor: (path: string) => string): MenuItem[] {
  const visible = (menu as Row[])
    .filter((m) => Number(m.status) === 1 && Number(m.status_header) === 1 && m.position === 'index')
    .sort((a, b) => Number(a.indexs) - Number(b.indexs) || a.id - b.id);

  const hrefOf = (m: Row): string | null => {
    if (m.type === 'content') return m.slug === 'privacy-policy' ? urlFor('privacy-policy') : urlFor(`page/${m.content}`);
    if (m.type === 'slug') return m.slug?.startsWith('/') ? m.slug.replace(/^\/th\//, `/${lang}/`) : urlFor(m.slug ?? '');
    if (!m.url || m.url === '#!') return null;
    if (m.url === '/') return urlFor('');
    return /^https?:/.test(m.url) ? m.url : urlFor(m.url);
  };

  return visible
    .filter((m) => m.level === 'main')
    .map((m) => {
      let children: MenuItem[];
      if (m.id === 9) {
        // "Services" lists categories flagged for the menu, with subcategories as a third level.
        children = getCategories()
          .filter((c) => c.is_show_menu === 'A')
          .map((c) => ({
            id: c.id,
            row: c,
            href: c.external_link || urlFor(`services/all/${c.id}/${slug(pick(c, 'name', lang))}`),
            children: getSubcategories(c.id).map((s) => ({
              id: s.id,
              row: s,
              href: urlFor(`services/all/${c.id}/${s.id}/${slug(pick(s, 'name', lang))}`),
              children: [],
            })),
          }));
      } else {
        children = visible
          .filter((s) => s.level === 'sub' && String(s.sub) === String(m.id))
          .map((s) => ({ id: s.id, row: s, href: hrefOf(s), children: [] }));
      }
      return { id: m.id, row: m, href: hrefOf(m), children };
    });
}
